
/* Only the gym survival page receives this visual treatment. */
const survivalPreviousPage=survivalPage;
const survivalPreviousHead=head;
head=function(){let html=survivalPreviousHead();return html.replace(/<a class="brand"[\s\S]*?<\/a>/,'<a class="brand survival-brand" href="#home" onclick="go(\'home\');return false"><img src="data:image/svg+xml;base64," alt="MOVEQUEST"></a>')};
survivalPage=function(){
 const original=survivalPreviousPage();
 const start=original.indexOf('<div class="zone-grid">');
 const end=original.indexOf('</div>',start)+6;
 const ids=[['treadmill','elliptical','spin','recumbent','erg','stairs','airbike'],['press','pulldown','legpress'],['dumbbell','barbell','rack','power'],['mat','roller','band']];
 const names=[T('有氧训练区','유산소 운동 구역','Cardio zone'),T('固定器械区','머신 운동 구역','Machine zone'),T('自由重量区','프리 웨이트 구역','Free weights'),T('垫上与伸展区','매트 및 스트레칭 구역','Mat & mobility')];
 const cards=zones.map((z,i)=>`<article class="survival-zone"><div class="survival-zone-copy"><h2>${tr(T('训练区域','훈련 구역','TRAINING ZONE'))} 0${i+1}</h2><p>${tr(z)}</p><div class="survival-equipment-links">${links(ids[i],'equipment')}</div></div><div class="survival-machine machine-${i}" role="img" aria-label="${tr(names[i])}"></div><span class="survival-slashes" aria-hidden="true">///</span></article>`).join('');
 const complete=scenarioV2.filter(s=>state.scenarios.includes(s.id)).length;
 let rest=original.slice(end).replace(/<h2>[\s\S]*?<\/h2>/,`<div class="survival-practice-heading"><h2>${tr(T('五项情境练习','다섯 가지 상황 연습','Five gym scenarios'))}</h2><span>${complete}/5</span><i aria-hidden="true">///</i></div>`);
 return `<section class="survival-intro"><span>01 / 07 — ${tr(modules[0][1])}</span><h1>${tr(modules[0][1])} <i aria-hidden="true">///</i></h1><p>${tr(modules[0][4])}</p></section><div class="survival-zones">${cards}</div><section class="survival-practice">${rest}</section>`;
};
const survivalPreviousRender=render;
render=function(){document.body.classList.toggle('survival-neon',['survival','muscle','equipment','move','sport','quest','passport'].includes(page));document.body.classList.toggle('module-neon',['muscle','equipment','move','sport','quest','passport'].includes(page));survivalPreviousRender()};
render();

